const requestBody = { ...$json.request_body };
requestBody.instructions = `${requestBody.instructions}\n12. Telegram'da gorsel, tam metin ve dugmeler tek mesajda gosterilecek. hook, body ve cta alanlarinin toplam uzunlugu 650-780 karakter arasinda olmali; 780 karakteri kesinlikle asma. Kaynak URL ve hashtagler bu sinira dahil degildir.`;
return [{ json: { request_body: requestBody } }];

const response = $json;
if (response.error) throw new Error('OpenAI error: ' + JSON.stringify(response.error));
if (response.status && response.status !== 'completed') throw new Error('OpenAI response status: ' + response.status);
const message = (response.output || []).find((item) => item.type === 'message');
const refusal = message?.content?.find((item) => item.type === 'refusal');
if (refusal) throw new Error('OpenAI refusal: ' + refusal.refusal);
const outputText = message?.content?.find((item) => item.type === 'output_text')?.text;
if (!outputText) throw new Error('OpenAI output_text bulunamadi');
const draft = JSON.parse(outputText);
const evidence = $('Reserve Evidence').first().json;
const required = ['pillar','hook','body','cta','hashtags','claims','image_brief','visual_spec','risk_flags'];
for (const key of required) if (!(key in draft)) throw new Error('Taslak alani eksik: ' + key);
const layouts = ["process_flow","layered_architecture","comparison","cause_effect","cycle"];
const icons = ["user","identity","shield","lock","network","server","database","sensor","plc","ai","energy","analytics","approval","decision","eye","pulse","cloud","gateway"];
function clean(value, max) { return String(value || '').replace(/\s+/g, ' ').trim().slice(0, max); }
function validateVisualSpec(spec) {
  if (!spec || !layouts.includes(spec.layout_type)) throw new Error('Gecersiz visual_spec layout_type');
  spec.technical_title = clean(spec.technical_title, 42);
  spec.international_name = clean(spec.international_name, 48);
  spec.curiosity_subtitle = clean(spec.curiosity_subtitle, 92);
  if (!Array.isArray(spec.stages) || spec.stages.length < 3 || spec.stages.length > 5) throw new Error('visual_spec stages 3-5 olmali');
  spec.stages = spec.stages.map((stage) => ({ label: clean(stage.label, 26), description: clean(stage.description, 58), icon: icons.includes(stage.icon) ? stage.icon : 'decision', state: ['normal','controlled','risk','outcome'].includes(stage.state) ? stage.state : 'normal' }));
  if (!Array.isArray(spec.connections) || spec.connections.length < 2 || spec.connections.length > 7) throw new Error('Gecersiz visual_spec connections');
  spec.connections = spec.connections.filter((edge) => Number.isInteger(edge.from) && Number.isInteger(edge.to) && edge.from >= 1 && edge.to >= 1 && edge.from <= spec.stages.length && edge.to <= spec.stages.length && edge.from !== edge.to && ['flow','allowed','blocked','conditional','bidirectional'].includes(edge.type));
  if (spec.connections.length < 2) throw new Error('Yetersiz gecerli visual_spec connection');
  if (!Array.isArray(spec.takeaways) || spec.takeaways.length < 3 || spec.takeaways.length > 4) throw new Error('visual_spec takeaways 3-4 olmali');
  spec.takeaways = spec.takeaways.map((item) => ({ label: clean(item.label, 24), description: clean(item.description, 46), icon: icons.includes(item.icon) ? item.icon : 'eye' }));
  return spec;
}
draft.visual_spec = validateVisualSpec(draft.visual_spec);
if (!Array.isArray(draft.hashtags) || draft.hashtags.length > 5) draft.risk_flags.push('HASHTAG_LIMIT');
if (!Array.isArray(draft.claims)) throw new Error('claims dizi olmali');
if (!Array.isArray(draft.risk_flags)) throw new Error('risk_flags dizi olmali');
const text = draft.hook + '\n' + draft.body + '\n' + draft.cta;
const numericClaim = /(?:%|yuzde|\b\d+(?:[.,]\d+)?\b)/i.test(text.replace(/4\.0/g, ''));
if (numericClaim && !draft.claims.some((claim) => claim.allowed)) draft.risk_flags.push('UNMAPPED_NUMERIC_CLAIM');
if (draft.claims.some((claim) => !claim.allowed)) draft.risk_flags.push('DISALLOWED_CLAIM');
if (evidence.kind === 'lab_demo' && !/(demo|simulasyon|sentetik)/i.test(text)) draft.risk_flags.push('DEMO_NOT_DISCLOSED');
if (evidence.confidentiality === 'private') draft.risk_flags.push('PRIVATE_EVIDENCE');
for (const claim of draft.claims) { if (claim.evidence_id !== evidence.id) { claim.allowed = false; claim.reason = 'Evidence ID eslesmiyor'; draft.risk_flags.push('EVIDENCE_ID_MISMATCH'); } }
const uniqueRisks = [...new Set(draft.risk_flags.filter(Boolean))];
return [{ json: { evidence_id: evidence.id, pillar: draft.pillar, hook: draft.hook.trim(), body: draft.body.trim(), cta: draft.cta.trim(), hashtags: draft.hashtags, claims: draft.claims, image_brief: draft.image_brief.trim(), visual_spec: draft.visual_spec, image_title: draft.visual_spec.technical_title + (draft.visual_spec.international_name ? ' (' + draft.visual_spec.international_name + ')' : ''), image_points: draft.visual_spec.takeaways.map((item) => item.label), risk_flags: uniqueRisks, approval_status: uniqueRisks.length ? 'blocked' : 'needs_review', text_model: response.model || 'gpt-6.1-terra', openai_response_id: response.id || null, token_usage: response.usage || null } }];

const draft = { ...$json };
const sourceRef = String($('Reserve Evidence').first().json.source_ref || '').trim();
const combined = `${draft.hook || ''} ${draft.body || ''} ${draft.cta || ''}`;
if (/^https?:\/\//i.test(sourceRef) && !combined.includes(sourceRef)) {
  draft.cta = `${String(draft.cta || '').trim()}\n\nKaynak: ${sourceRef}`.trim();
}
return [{ json: draft }];
